content:
:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --bg-gradient: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
  --card-bg: rgba(30, 41, 59, 0.7);
  --card-border: rgba(255, 255, 255, 0.08);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --primary-color: #ef4444;
  --primary-hover: #dc2626;
  --secondary-bg: rgba(255, 255, 255, 0.07);
  --secondary-hover: rgba(255, 255, 255, 0.12);
  --secondary-text: #e2e8f0;
  --danger-color: #64748b;
  --danger-hover: #475569;
  --accent-glow: rgba(239, 68, 68, 0.25);
  --progress-track: rgba(255, 255, 255, 0.08);
  --shadow-card: 0 20px 40px -15px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  width: 100%;
}

.app-container {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 24px 16px;
}

.timer-card {
  width: 100%;
  max-width: 440px;
  background: var(--card-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--card-border);
  border-radius: 24px;
  padding: 36px 28px;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  color: var(--text-main);
  margin-bottom: 6px;
}

.app-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 24px;
}

.mode-selector {
  display: flex;
  background: rgba(15, 23, 42, 0.6);
  padding: 5px;
  border-radius: 9999px;
  gap: 4px;
  width: 100%;
  margin-bottom: 28px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.mode-btn {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  padding: 10px 12px;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  white-space: nowrap;
}

.mode-btn:hover:not(:disabled) {
  color: var(--text-main);
}

.mode-btn-active {
  background: var(--primary-color);
  color: #ffffff;
  box-shadow: 0 4px 12px var(--accent-glow);
}

.mode-btn-active:hover {
  color: #ffffff;
}

.timer-display-container {
  position: relative;
  width: 250px;
  height: 250px;
  margin: 0 auto 28px auto;
  display: flex;
  justify-content: center;
  align-items: center;
}

.timer-svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
  overflow: visible;
}

.timer-circle-bg {
  fill: none;
  stroke: var(--progress-track);
  stroke-width: 8;
}

.timer-circle-progress {
  fill: none;
  stroke: var(--primary-color);
  stroke-width: 8;
  stroke-linecap: round;
  transition: stroke-dashoffset 0.8s ease, stroke 0.3s ease;
  filter: drop-shadow(0 0 6px var(--accent-glow));
}

.timer-text-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  pointer-events: none;
}

.timer-time {
  font-size: 3.25rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.04em;
  color: var(--text-main);
  line-height: 1;
}

.timer-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  margin-top: 8px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.controls-container {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  margin-bottom: 24px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  outline: none;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: 14px;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  user-select: none;
  touch-action: manipulation;
}

.btn:active {
  transform: scale(0.96);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.btn-primary {
  flex: 1.5;
  padding: 14px 24px;
  background: var(--primary-color);
  color: #ffffff;
  box-shadow: 0 4px 16px var(--accent-glow);
}

.btn-primary:hover:not(:disabled) {
  background: var(--primary-hover);
  box-shadow: 0 6px 20px rgba(239, 68, 68, 0.35);
}

.btn-secondary {
  flex: 1;
  padding: 14px 18px;
  background: var(--secondary-bg);
  color: var(--secondary-text);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--secondary-hover);
  color: #ffffff;
}

.btn-danger {
  flex: 1;
  padding: 14px 18px;
  background: var(--danger-color);
  color: #ffffff;
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
}

.stats-container {
  display: flex;
  justify-content: space-around;
  width: 100%;
  padding-top: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 12px;
}

.stats-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stats-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.2;
}

.stats-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.notification-note {
  font-size: 0.75rem;
  color: var(--text-muted);
  opacity: 0.75;
  margin-top: 8px;
}

@media (max-width: 480px) {
  .timer-card {
    padding: 28px 18px;
    border-radius: 20px;
  }

  .timer-display-container {
    width: 220px;
    height: 220px;
    margin-bottom: 22px;
  }

  .timer-time {
    font-size: 2.85rem;
  }

  .mode-btn {
    padding: 8px 10px;
    font-size: 0.8125rem;
  }

  .controls-container {
    gap: 8px;
  }

  .btn {
    padding: 12px 14px;
    font-size: 0.875rem;
  }
}

export type TimerMode = 'work' | 'shortBreak' | 'longBreak';

export interface ModeConfig {
  label: string;
  durationSeconds: number;
}

export interface TimerState {
  mode: TimerMode;
  timeLeft: number;
  isRunning: boolean;
  completedPomodoros: number;
}

export interface TimerDisplayProps {
  timeLeft: number;
  totalDuration: number;
  mode: TimerMode;
  modeLabel: string;
}

export interface ControlsProps {
  isRunning: boolean;
  onToggle: () => void;
  onReset: () => void;
  onSkip: () => void;
}

export interface ModeSelectorProps {
  currentMode: TimerMode;
  onSelectMode: (mode: TimerMode) => void;
  isRunning: boolean;
}

import { ModeSelectorProps, TimerMode } from '../types';

interface ModeOption {
  key: TimerMode;
  label: string;
}

const MODES: ModeOption[] = [
  { key: 'work', label: '作業 (25分)' },
  { key: 'shortBreak', label: '短休憩 (5分)' },
  { key: 'longBreak', label: '長休憩 (15分)' },
];

const ModeSelector = ({
  currentMode,
  onSelectMode,
  isRunning,
}: ModeSelectorProps) => {
  return (
    <div className="mode-selector" role="tablist" aria-label="タイマーモード選択">
      {MODES.map((item) => {
        const isActive = currentMode === item.key;
        const className = isActive ? 'mode-btn mode-btn-active' : 'mode-btn';

        return (
          <button
            key={item.key}
            type="button"
            role="tab"
            aria-selected={isActive}
            className={className}
            onClick={() => onSelectMode(item.key)}
            disabled={isRunning && isActive}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  );
};

export default ModeSelector;

import { TimerDisplayProps } from '../types';

const TimerDisplay = ({
  timeLeft,
  totalDuration,
  mode,
  modeLabel,
}: TimerDisplayProps) => {
  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formattedTime = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  const radius = 105;
  const circumference = 2 * Math.PI * radius;
  const safeTotal = totalDuration > 0 ? totalDuration : 1;
  const progressRatio = Math.max(0, Math.min(1, timeLeft / safeTotal));
  const strokeDashoffset = circumference * (1 - progressRatio);

  const getModeColor = () => {
    switch (mode) {
      case 'shortBreak':
        return '#10b981';
      case 'longBreak':
        return '#3b82f6';
      case 'work':
      default:
        return '#ef4444';
    }
  };

  const getModeGlow = () => {
    switch (mode) {
      case 'shortBreak':
        return 'rgba(16, 185, 129, 0.35)';
      case 'longBreak':
        return 'rgba(59, 130, 246, 0.35)';
      case 'work':
      default:
        return 'rgba(239, 68, 68, 0.35)';
    }
  };

  return (
    <div className="timer-display-container">
      <svg className="timer-svg" viewBox="0 0 240 240">
        <circle
          className="timer-circle-bg"
          cx="120"
          cy="120"
          r={radius}
        />
        <circle
          className="timer-circle-progress"
          cx="120"
          cy="120"
          r={radius}
          style={{
            strokeDasharray: circumference,
            strokeDashoffset: strokeDashoffset,
            stroke: getModeColor(),
            filter: `drop-shadow(0 0 8px ${getModeGlow()})`,
          }}
        />
      </svg>
      <div className="timer-text-container">
        <div className="timer-time" aria-live="polite">
          {formattedTime}
        </div>
        <div className="timer-label">{modeLabel}</div>
      </div>
    </div>
  );
};

export default TimerDisplay;

import { Play, Pause, RotateCcw, SkipForward } from 'lucide-react';
import { ControlsProps } from '../types';

const Controls = ({
  isRunning,
  onToggle,
  onReset,
  onSkip,
}: ControlsProps) => {
  return (
    <div className="controls-container">
      <button
        type="button"
        className="btn btn-primary"
        onClick={() => onToggle?.()}
        aria-label={isRunning ? '一時停止' : 'タイマー開始'}
      >
        {isRunning ? (
          <>
            <Pause size={18} />
            <span>一時停止</span>
          </>
        ) : (
          <>
            <Play size={18} />
            <span>開始</span>
          </>
        )}
      </button>

      <button
        type="button"
        className="btn btn-danger"
        onClick={() => onReset?.()}
        aria-label="タイマーをリセット"
      >
        <RotateCcw size={17} />
        <span>リセット</span>
      </button>

      <button
        type="button"
        className="btn btn-secondary"
        onClick={() => onSkip?.()}
        aria-label="次のセッションへスキップ"
      >
        <SkipForward size={17} />
        <span>スキップ</span>
      </button>
    </div>
  );
};

export default Controls;

import { useState, useEffect, useRef, useCallback } from 'react';
import { TimerMode, ModeConfig } from './types';
import ModeSelector from './components/ModeSelector';
import TimerDisplay from './components/TimerDisplay';
import Controls from './components/Controls';

const MODE_CONFIGS: Record<TimerMode, ModeConfig> = {
  work: {
    label: '作業時間',
    durationSeconds: 25 * 60,
  },
  shortBreak: {
    label: '短休憩',
    durationSeconds: 5 * 60,
  },
  longBreak: {
    label: '長休憩',
    durationSeconds: 15 * 60,
  },
};

const playCompletionSound = () => {
  try {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AudioContextClass) return;
    const ctx = new AudioContextClass();

    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((freq, idx) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.12);

      gain.gain.setValueAtTime(0, ctx.currentTime + idx * 0.12);
      gain.gain.linearRampToValueAtTime(0.2, ctx.currentTime + idx * 0.12 + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.12 + 0.35);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(ctx.currentTime + idx * 0.12);
      osc.stop(ctx.currentTime + idx * 0.12 + 0.4);
    });
  } catch {
    // Web Audio非対応またはブロック時のフォールバック（無視）
  }
};

const App = () => {
  const [mode, setMode] = useState<TimerMode>('work');
  const [timeLeft, setTimeLeft] = useState<number>(MODE_CONFIGS.work.durationSeconds);
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const [completedPomodoros, setCompletedPomodoros] = useState<number>(0);
  const [totalSessions, setTotalSessions] = useState<number>(0);

  const activeModeRef = useRef<TimerMode>(mode);
  activeModeRef.current = mode;

  const currentDuration = MODE_CONFIGS[mode].durationSeconds;

  const handleNextMode = useCallback(() => {
    playCompletionSound();
    setTotalSessions((prev) => prev + 1);

    if (activeModeRef.current === 'work') {
      const nextCount = completedPomodoros + 1;
      setCompletedPomodoros(nextCount);

      if (nextCount > 0 && nextCount % 4 === 0) {
        setMode('longBreak');
        setTimeLeft(MODE_CONFIGS.longBreak.durationSeconds);
      } else {
        setMode('shortBreak');
        setTimeLeft(MODE_CONFIGS.shortBreak.durationSeconds);
      }
    } else {
      setMode('work');
      setTimeLeft(MODE_CONFIGS.work.durationSeconds);
    }
    setIsRunning(false);
  }, [completedPomodoros]);

  useEffect(() => {
    let timerId: number | undefined;

    if (isRunning) {
      timerId = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            clearInterval(timerId);
            handleNextMode();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }

    return () => {
      if (timerId !== undefined) {
        clearInterval(timerId);
      }
    };
  }, [isRunning, handleNextMode]);

  useEffect(() => {
    const mins = Math.floor(timeLeft / 60);
    const secs = timeLeft % 60;
    const timeFormatted = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
    const modeName = MODE_CONFIGS[mode].label;
    document.title = `${timeFormatted} - ${modeName} | ポモドーロタイマー`;

    return () => {
      document.title = 'ポモドーロタイマー';
    };
  }, [timeLeft, mode]);

  const handleToggle = () => {
    setIsRunning((prev) => !prev);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTimeLeft(MODE_CONFIGS[mode].durationSeconds);
  };

  const handleSkip = () => {
    setIsRunning(false);
    if (mode === 'work') {
      setMode('shortBreak');
      setTimeLeft(MODE_CONFIGS.shortBreak.durationSeconds);
    } else {
      setMode('work');
      setTimeLeft(MODE_CONFIGS.work.durationSeconds);
    }
  };

  const handleSelectMode = (newMode: TimerMode) => {
    setIsRunning(false);
    setMode(newMode);
    setTimeLeft(MODE_CONFIGS[newMode].durationSeconds);
  };

  return (
    <div className="app-container">
      <main className="timer-card">
        <h1 className="app-title">ポモドーロタイマー</h1>
        <p className="app-subtitle">25分の集中と休憩のリズムで生産性を最大化</p>

        <ModeSelector
          currentMode={mode}
          onSelectMode={handleSelectMode}
          isRunning={isRunning}
        />

        <TimerDisplay
          timeLeft={timeLeft}
          totalDuration={currentDuration}
          mode={mode}
          modeLabel={MODE_CONFIGS[mode].label}
        />

        <Controls
          isRunning={isRunning}
          onToggle={handleToggle}
          onReset={handleReset}
          onSkip={handleSkip}
        />

        <section className="stats-container" aria-label="統計情報">
          <div className="stats-item">
            <span className="stats-value">{completedPomodoros}</span>
            <span className="stats-label">完了ポモドーロ</span>
          </div>
          <div className="stats-item">
            <span className="stats-value">{completedPomodoros % 4} / 4</span>
            <span className="stats-label">現在のサイクル</span>
          </div>
          <div className="stats-item">
            <span className="stats-value">{totalSessions}</span>
            <span className="stats-label">総セッション数</span>
          </div>
        </section>

        <p className="notification-note">
          ※ タイマー終了時に通知サウンドが鳴ります（4回作業完了で長休憩）
        </p>
      </main>
    </div>
  );
};

export default App;
